```java
// OOP Java — the object encapsulates and protects its state
public class BankAccount {
    private double balance;  // private: only this class can touch it

    public BankAccount(double openingBalance) {
        if (openingBalance < 0) throw new IllegalArgumentException();
        this.balance = openingBalance;
    }

    public void withdraw(double amount) {
        if (amount > balance)
            throw new IllegalStateException("Insufficient funds");
        if (amount <= 0)
            throw new IllegalArgumentException("Amount must be positive");
        this.balance -= amount;  // invariant maintained: balance >= 0
    }

    public double getBalance() { return balance; }  // read-only access
}

// Now no external code can set balance to -1000. The object enforces its own
// invariants. processFees() would have to call account.withdraw(50), and the
// account decides whether that's allowed.
```

